import fs from 'fs';import path from 'path';const ROOT='sep18-final-sidebar-combined',rows=[];function walk(d){if(!fs.existsSync(d))return;for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())walk(p);else if(e.name==='result.json'){try{rows.push(JSON.parse(fs.readFileSync(p,'utf8')))}catch{}}}}walk(ROOT);const pass=rows.filter(r=>r.httpStatus===200&&r.previewOk&&!r.error&&!r.sidebarError&&r.triggerVisible&&!r.invalidHrefs.length&&!r.brokenImages),fail=rows.filter(r=>!pass.includes(r));const summary={generatedAt:new Date().toISOString(),total:rows.length,passed:pass.length,failed:fail.length,totalCategories:pass.reduce((s,r)=>s+r.categoryCount,0),totalSubcategories:pass.reduce((s,r)=>s+r.subcategoryCount,0),totalTypes:pass.reduce((s,r)=>s+r.typeCount,0),averageLoadMs:pass.length?Math.round(pass.reduce((s,r)=>s+(r.loadMs||0),0)/pass.length):0,failures:fail.map(r=>({label:r.label,route:r.route,http:r.httpStatus,previewOk:r.previewOk,triggerVisible:r.triggerVisible,invalidHrefs:r.invalidHrefs?.length,brokenImages:r.brokenImages,error:r.error||r.sidebarError,attemptHistory:r.attemptHistory})),rows};fs.mkdirSync('sep18-final-sidebar-final',{recursive:true});fs.writeFileSync('sep18-final-sidebar-final/summary.json',JSON.stringify(summary,null,2));fs.writeFileSync('sep18-final-sidebar-final/AUDIT.md',['# Final State Guard Sidebar Certification','',`Components: ${summary.total}; passed: ${summary.passed}; failed: ${summary.failed}`,`Categories: ${summary.totalCategories}; subcategories: ${summary.totalSubcategories}; type links sampled: ${summary.totalTypes}`,`Average load: ${summary.averageLoadMs} ms`,'','## Failures',...summary.failures.map(x=>`- ${x.label}: HTTP ${x.http}, trigger=${x.triggerVisible}, invalid links=${x.invalidHrefs}, broken images=${x.brokenImages}`)].join('\n'));console.log('FINALSIDEBARSUMMARY',JSON.stringify(summary));if(fail.length)process.exitCode=2;